 useEffect(()=>{const ctx=(document as any).modelContext;if(!ctx?.registerTool)return;const lifecycle=new AbortController();const tools=[{name:'read_car_recommendations',title:'추천 차량 확인',description:'현재 구매조건에 따른 추천 후보와 설명을 읽습니다. 모든 비용은 예시 기준입니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({profile,recommendations:uniqueRecommendations.map(x=>({id:x.car.id,model:x.ev!.model.name,score:x.ev!.score,monthly:[x.ev!.low,x.ev!.high],eligible:x.ev!.eligible,reasons:x.ev!.reasons}))})},{name:'configure_purchase_conditions',title:'구매조건 설정',description:'화면의 구매조건을 변경합니다. 계정에 저장하지 않습니다.',inputSchema:{type:'object',properties:{budget:{type:'number',minimum:100,maximum:100000},monthly:{type:'number',minimum:5,maximum:2000},annualkm:{type:'number',minimum:0,maximum:200000}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async(input:any)=>{if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).some(k=>!['budget','monthly','annualkm'].includes(k)))throw new Error('허용되지 않는 조건입니다.');const next=profileSchema.parse({...profile,...input});changeProfile(next);await new Promise<void>(resolve=>requestAnimationFrame(()=>requestAnimationFrame(()=>resolve())));return {saved:false,profile:next}}}];for(const t of tools)Promise.resolve(ctx.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});return()=>lifecycle.abort()},[profile,uniqueRecommendations]);
